-- Land Fee MVP — Savannakhet Province
-- Seed: districts + villages copied VERBATIM from tax_ets MySQL (apis.com.la)
-- NOTE: Lao/English district names are misaligned for codes 1311-1315 in the
-- tax_ets source (Lao column shifted by one). Verify with PERN before relying on it.

SET search_path = landfee;

-- Idempotent: clear tables in FK order before reloading
TRUNCATE zones_rates, villages, districts RESTART IDENTITY CASCADE;

-- Districts

-- Villages

-- Zone rates (placeholder 80-180k band, per road category)
SELECT d.id, rc.rc, rc.rate, CURRENT_DATE
FROM districts d CROSS JOIN (
  SELECT 'main' AS rc, 180000.00 AS rate UNION ALL
  SELECT 'branch', 140000.00 UNION ALL
  SELECT 'alley', 110000.00 UNION ALL
  SELECT 'none', 85000.00) rc;